import UIKit

/// Exact current-main PenArt paths. These trusted, compiled M/L/C/Z words
/// are cached as geometry only; every native size is drawn at its own scale.
@MainActor
enum SettingsPenArt {
    private static var paths: [String: CGPath] = [:]
    static var names: [String] { ink.keys.sorted() }
    static var markerNames: [String] { marker.keys.sorted() }

    static func image(_ name: String, marker isMarker: Bool = false) -> UIImage? {
        guard let path = path(name, marker: isMarker) else { return nil }
        let format = UIGraphicsImageRendererFormat(); format.scale = 3
        return UIGraphicsImageRenderer(size: CGSize(width: 24, height: 24), format: format).image { output in
            draw(path, color: .black, in: CGRect(x: 0, y: 0, width: 24, height: 24), context: output.cgContext)
        }.withRenderingMode(.alwaysTemplate)
    }

    static func drawTile(_ name: String, tint: UIColor?, in rect: CGRect, dark: Bool, context: CGContext) {
        let radius = rect.width * 0.25
        let paper = UIBezierPath(roundedRect: rect, cornerRadius: radius)
        let color = dark ? UIColor(red: 0.169, green: 0.169, blue: 0.184, alpha: 1)
                         : UIColor(red: 0.984, green: 0.98, blue: 0.973, alpha: 1)
        context.setFillColor(color.cgColor); context.addPath(paper.cgPath); context.fillPath()
        let line = max(0.5, rect.width / 56)
        let rim = UIBezierPath(roundedRect: rect.insetBy(dx: line / 2, dy: line / 2), cornerRadius: radius - line / 2)
        context.setStrokeColor((dark ? UIColor.white : .black).withAlphaComponent(0.1).cgColor)
        context.setLineWidth(line); context.addPath(rim.cgPath); context.strokePath()
        if let tint, let swipe = path(name, marker: true) {
            context.saveGState(); context.setAlpha(name == "about" ? 1 : (dark ? 0.75 : 0.6))
            draw(swipe, color: tint, in: rect, context: context); context.restoreGState()
        }
        if let art = path(name, marker: false) {
            let ink = dark ? UIColor(red: 0.945, green: 0.945, blue: 0.953, alpha: 1)
                           : UIColor(red: 0.11, green: 0.11, blue: 0.118, alpha: 1)
            draw(art, color: ink, in: rect, context: context)
        }
    }

    private static func draw(_ path: CGPath, color: UIColor, in rect: CGRect, context: CGContext) {
        context.saveGState()
        context.translateBy(x: rect.minX, y: rect.minY)
        context.scaleBy(x: rect.width / 384, y: rect.height / 384)
        context.translateBy(x: 0, y: 384); context.scaleBy(x: 0.1, y: -0.1)
        context.setFillColor(color.cgColor); context.addPath(path); context.fillPath(using: .winding)
        context.restoreGState()
    }

    private static func path(_ name: String, marker isMarker: Bool) -> CGPath? {
        let key = name + (isMarker ? ".marker" : ".ink")
        if let hit = paths[key] { return hit }
        guard let words = (isMarker ? marker : ink)[name] else { return nil }
        let tokens = words.split(whereSeparator: \.isWhitespace)
        let made = CGMutablePath(); var i = 0
        while i < tokens.count {
            let command = tokens[i]; i += 1
            let count: Int
            switch command { case "M", "L": count = 2; case "C": count = 6; case "Z": count = 0; default: return nil }
            guard i + count <= tokens.count else { return nil }
            let values = tokens[i..<(i + count)].compactMap { Double($0) }.map { CGFloat($0) }
            guard values.count == count, values.allSatisfy(\.isFinite) else { return nil }; i += count
            switch command {
            case "M": made.move(to: CGPoint(x: values[0], y: values[1]))
            case "L": made.addLine(to: CGPoint(x: values[0], y: values[1]))
            case "C": made.addCurve(to: CGPoint(x: values[4], y: values[5]),
                                     control1: CGPoint(x: values[0], y: values[1]), control2: CGPoint(x: values[2], y: values[3]))
            case "Z": made.closeSubpath()
            default: return nil
            }
        }
        let frozen = made.copy()!; paths[key] = frozen
        return frozen
    }

